def _get_stable_hash(obj):
    """Get a somewhat stable hash for tracking objects"""
    try:
        if hasattr(obj, '__array__'):
            arr = obj.__array__()
            if hasattr(arr, 'shape') and hasattr(arr, 'dtype'):
                return hash((arr.shape, str(arr.dtype), arr.size))
        return id(obj) % 10000
    except:
        return id(obj) % 10000

